verus! {

    /// Given a vector of 32‐bit floats, returns a new vector with the elements in reverse order.
    fn numpy_flip(m: Vec<f32>) -> (result: Vec<f32>)
        ensures
            // The output has the same length as the input
            result.len() == m.len(),
            // For every index i in [0, m.len()),
            // result[i] == m[m.len() - 1 - i]
            forall |i: usize| i < m.len() ==> result[i] == m[m.len() - 1 - i],
    {
        let n: usize = m.len();
        let mut result: Vec<f32> = Vec::new();
        let mut i: usize = 0;
        while i < n
            invariant
                // i never exceeds n
                i <= n,
                // We have pushed exactly i elements so far
                result.len() == i,
                // And those i elements satisfy the reverse‐prefix property:
                // for every j < i, result[j] == m[n - 1 - j]
                forall |j: usize| j < i ==> result[j] == m[n - 1 - j],
            decreases n - i,
        {
            // Compute the source index in m
            let idx: usize = n - 1 - i;
            // Justify safe indexing
            assert(idx < n);
            // Extract the element
            let val_ref: &f32 = m.get(idx).unwrap();
            let val: f32 = *val_ref;
            // Push it onto the result
            result.push(val);
            // Advance the loop counter
            i += 1;
        }
        result
    }

} // end of verus! block

